def create_local_node(apps, schema_editor):
    """
    Create a local node automatically based on environment.
    Uses DJANGO_HOST env var or defaults to http://127.0.0.1:8000
    """
    Node = apps.get_model('nodes', 'Node')
    
    # Only create if no local node exists
    if not Node.objects.filter(is_local=True).exists():
        # Get host URL from environment variable or use default
        host_url = os.environ.get('DJANGO_HOST', 'http://127.0.0.1:8000')
        
